package ui;

import dao.NotificationDAO;import model.Notification;import model.User;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.time.format.DateTimeFormatter;import java.util.List;

public class NotificationsFrame extends JFrame {
    public NotificationsFrame(User user,Runnable onClose){NotificationDAO dao=new NotificationDAO();UITheme.styleFrame(this,"Notifications",820,520);setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(0,14));root.setBackground(UITheme.BG);root.setBorder(BorderFactory.createEmptyBorder(22,26,22,26));JPanel head=new JPanel(new BorderLayout());head.setOpaque(false);JPanel h=new JPanel();h.setOpaque(false);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.add(UITheme.title("Notifications",24));h.add(Box.createVerticalStrut(4));h.add(UITheme.muted("Your latest notice updates and announcements."));head.add(h,BorderLayout.WEST);JButton close=UITheme.button("Close",false);close.addActionListener(e->dispose());head.add(close,BorderLayout.EAST);root.add(head,BorderLayout.NORTH);
        DefaultTableModel model=new DefaultTableModel(new String[]{"Message","Date","Status"},0){public boolean isCellEditable(int r,int c){return false;}};DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm");List<Notification> list=dao.getNotificationsForUser(user.getUserId());for(Notification n:list)model.addRow(new Object[]{n.getMessage(),n.getCreatedAt()==null?"":n.getCreatedAt().format(fmt),n.isRead()?"Read":"NEW"});JTable table=new JTable(model);UITheme.styleTable(table);UITheme.styleBadgeRenderer(table,2);table.getColumnModel().getColumn(0).setPreferredWidth(470);root.add(new JScrollPane(table),BorderLayout.CENTER);setContentPane(root);dao.markAllRead(user.getUserId());addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){if(onClose!=null)onClose.run();}});setVisible(true);}
}
